ALTER TABLE disposal_order   ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS created_by BIGINT, ADD COLUMN IF NOT EXISTS updated_by BIGINT;
